INSERT INTO public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('Парламентский законодательный процесс','Принятый федеральный закон после прохождения парламента направляется Президенту для подписания. Какой срок предусмотрен для направления?','["В течение четырнадцати дней","В течение пяти дней","Только по окончании календарного года","В течение одного месяца"]'::jsonb,1,'Конституция Российской Федерации','статья 107','https://www.consultant.ru/document/cons_doc_LAW_28399/bdb6e3b84ca23ec909e111e3d18908e25a355111/','Основание: статья 107 Конституция Российской Федерации.',true),
('Парламентский законодательный процесс','Какой общий срок установлен Президенту РФ для подписания и обнародования федерального закона?','["Тридцать дней","Шесть месяцев","Четырнадцать дней","Пятьдесят дней"]'::jsonb,2,'Конституция Российской Федерации','статья 107','https://www.consultant.ru/document/cons_doc_LAW_28399/bdb6e3b84ca23ec909e111e3d18908e25a355111/','Основание: статья 107 Конституция Российской Федерации.',true),
('Парламентский законодательный процесс','Президент отклонил обычный федеральный закон. Какое большинство необходимо каждой палате для преодоления вето в прежней редакции?','["Большинство исключительно присутствующих","Единогласие только Совета Федерации","Одна треть от общего числа каждой палаты","Не менее двух третей от общего числа сенаторов и депутатов соответствующей палаты"]'::jsonb,3,'Конституция Российской Федерации','статья 107','https://www.consultant.ru/document/cons_doc_LAW_28399/bdb6e3b84ca23ec909e111e3d18908e25a355111/','Основание: статья 107 Конституция Российской Федерации.',true),
('Парламентский законодательный процесс','Если обе палаты преодолели президентское вето в установленном порядке, каков срок подписания закона Президентом по общему правилу?','["Семь дней","Один месяц","Три месяца","Шестьдесят дней"]'::jsonb,0,'Конституция Российской Федерации','статья 107','https://www.consultant.ru/document/cons_doc_LAW_28399/bdb6e3b84ca23ec909e111e3d18908e25a355111/','Основание: статья 107 Конституция Российской Федерации.',true),
('Парламентский законодательный процесс','Когда Президент обратился в Конституционный Суд для проверки конституционности федерального закона в рамках статьи 107, что происходит со сроком подписания?','["Он всегда истекает независимо от запроса","Он приостанавливается на время рассмотрения запроса Конституционным Судом","Он автоматически сокращается до одного дня","Он передаётся на усмотрение Правительства"]'::jsonb,1,'Конституция Российской Федерации','статья 107','https://www.consultant.ru/document/cons_doc_LAW_28399/bdb6e3b84ca23ec909e111e3d18908e25a355111/','Основание: статья 107 Конституция Российской Федерации.',true),
('Государственная Дума: роспуск','Кто может распустить Государственную Думу в предусмотренных Конституцией случаях?','["Председатель Государственной Думы лично","Председатель Правительства распоряжением","Президент Российской Федерации","Совет Федерации собственным постановлением"]'::jsonb,2,'Конституция Российской Федерации','статья 109','https://www.consultant.ru/document/cons_doc_LAW_28399/8ffd5c4f8a40189ec0dec930580718d280e863ea/','Основание: статья 109 Конституция Российской Федерации.',true),
('Государственная Дума: роспуск','После роспуска Государственной Думы когда должна собраться вновь избранная Дума?','["Не позднее двенадцати месяцев","Только после очередного бюджетного цикла","Ровно через шесть лет","Не позднее четырёх месяцев с момента роспуска"]'::jsonb,3,'Конституция Российской Федерации','статья 109','https://www.consultant.ru/document/cons_doc_LAW_28399/8ffd5c4f8a40189ec0dec930580718d280e863ea/','Основание: статья 109 Конституция Российской Федерации.',true),
('Государственная Дума: роспуск','Можно ли распустить Государственную Думу по основаниям статьи 117 в течение года после её избрания?','["Нет","Да, без каких-либо ограничений","Да, по инициативе Конституционного Суда","Да, если Совет Федерации одобрит двумя третями"]'::jsonb,0,'Конституция Российской Федерации','статья 109','https://www.consultant.ru/document/cons_doc_LAW_28399/8ffd5c4f8a40189ec0dec930580718d280e863ea/','Основание: статья 109 Конституция Российской Федерации.',true),
('Государственная Дума: роспуск','Может ли Государственная Дума быть распущена в период военного или чрезвычайного положения на всей территории Российской Федерации?','["Да, при любом выражении недоверия","Нет","Да, по решению Правительства","Да, по решению муниципальных депутатов"]'::jsonb,1,'Конституция Российской Федерации','статья 109','https://www.consultant.ru/document/cons_doc_LAW_28399/8ffd5c4f8a40189ec0dec930580718d280e863ea/','Основание: статья 109 Конституция Российской Федерации.',true),
('Государственная Дума: роспуск','Какое ограничение на роспуск Государственной Думы связано с окончанием срока полномочий Президента?','["Ограничение действует только за один месяц","Ограничение действует исключительно в год избрания Думы","Роспуск запрещён в течение шести месяцев до окончания срока полномочий Президента","Срок окончания президентских полномочий не имеет значения"]'::jsonb,2,'Конституция Российской Федерации','статья 109','https://www.consultant.ru/document/cons_doc_LAW_28399/8ffd5c4f8a40189ec0dec930580718d280e863ea/','Основание: статья 109 Конституция Российской Федерации.',true),
('Местное самоуправление: референдум','Кто принимает решение о назначении местного референдума в обычном порядке по статье 43 закона № 33-ФЗ?','["Федеральный министр финансов","Конституционный Суд в каждом случае","Коммерческий оператор портала услуг","Представительный орган муниципального образования"]'::jsonb,3,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 43','https://www.consultant.ru/document/cons_doc_LAW_501319/fa3b44e1c4c827fa1123259368666478868cfd6f/','Основание: статья 43 Федеральный закон от 20.03.2025 № 33-ФЗ.',true),
('Местное самоуправление: референдум','Какая максимальная доля подписей участников референдума может требоваться для инициативы граждан по статье 43 закона № 33-ФЗ?','["Не более пяти процентов","Не менее половины участников","Не менее трёх четвертей","Ровно двадцать процентов"]'::jsonb,0,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 43','https://www.consultant.ru/document/cons_doc_LAW_501319/fa3b44e1c4c827fa1123259368666478868cfd6f/','Основание: статья 43 Федеральный закон от 20.03.2025 № 33-ФЗ.',true),
('Местное самоуправление: референдум','Каков срок назначения местного референдума представительным органом после получения необходимых документов?','["Полгода","Тридцать дней","Два года","Три месяца"]'::jsonb,1,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 43','https://www.consultant.ru/document/cons_doc_LAW_501319/fa3b44e1c4c827fa1123259368666478868cfd6f/','Основание: статья 43 Федеральный закон от 20.03.2025 № 33-ФЗ.',true),
('Местное самоуправление: референдум','Кем может быть назначен местный референдум, если представительный орган не назначил его в установленный срок и поступило надлежащее обращение?','["Федеральным казначейством","Советом Федерации","Судом","Министром внутренних дел своим приказом"]'::jsonb,2,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 43','https://www.consultant.ru/document/cons_doc_LAW_501319/fa3b44e1c4c827fa1123259368666478868cfd6f/','Основание: статья 43 Федеральный закон от 20.03.2025 № 33-ФЗ.',true),
('Местное самоуправление: референдум','Требует ли решение, принятое на местном референдуме, дополнительного утверждения органом публичной власти?','["Да, всегда Правительством РФ","Да, только Советом Федерации","Да, только законодательным органом субъекта","Нет, подлежит исполнению без такого утверждения"]'::jsonb,3,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 43','https://www.consultant.ru/document/cons_doc_LAW_501319/fa3b44e1c4c827fa1123259368666478868cfd6f/','Основание: статья 43 Федеральный закон от 20.03.2025 № 33-ФЗ.',true)
